-- Frozen schema 2 and synthetic shared unknown-fields fixture, baseline b716694. One statement per line.
CREATE TABLE IF NOT EXISTS `records` (`id` TEXT NOT NULL, `titleJson` TEXT NOT NULL, `noteJson` TEXT NOT NULL, `occurredAtJson` TEXT NOT NULL, `createdAtJson` TEXT NOT NULL, `assetIdsJson` TEXT NOT NULL, `isOutfitJson` TEXT NOT NULL, `linksJson` TEXT NOT NULL, `tombstoneJson` TEXT NOT NULL, `extensionsJson` TEXT NOT NULL, `unknownFieldsJson` TEXT NOT NULL, `mediaOverflow` INTEGER, `outfitConstraintOverflow` INTEGER, PRIMARY KEY(`id`));
CREATE TABLE IF NOT EXISTS `items` (`id` TEXT NOT NULL, `nameJson` TEXT NOT NULL, `categoryJson` TEXT NOT NULL, `coverAssetIdJson` TEXT NOT NULL, `createdAtJson` TEXT NOT NULL, `tombstoneJson` TEXT NOT NULL, `extensionsJson` TEXT NOT NULL, `unknownFieldsJson` TEXT NOT NULL, PRIMARY KEY(`id`));
CREATE TABLE IF NOT EXISTS `assets` (`id` TEXT NOT NULL, `kind` TEXT NOT NULL, `capturedAtJson` TEXT NOT NULL, `resourceIdsJson` TEXT NOT NULL, `extensionsJson` TEXT NOT NULL, `unknownFieldsJson` TEXT NOT NULL, PRIMARY KEY(`id`));
CREATE TABLE IF NOT EXISTS `resources` (`id` TEXT NOT NULL, `assetId` TEXT NOT NULL, `role` TEXT NOT NULL, `contentType` TEXT NOT NULL, `originalFilename` TEXT NOT NULL, `byteCount` INTEGER NOT NULL, `sha256` TEXT NOT NULL, `objectKey` TEXT NOT NULL, `possibleDuplicateOfJson` TEXT, `extensionsJson` TEXT NOT NULL, `unknownFieldsJson` TEXT NOT NULL, PRIMARY KEY(`id`));
CREATE TABLE IF NOT EXISTS `snapshot_meta` (`id` INTEGER NOT NULL, `version` INTEGER NOT NULL, `extensionsJson` TEXT NOT NULL, `unknownFieldsJson` TEXT NOT NULL, PRIMARY KEY(`id`));
CREATE TABLE IF NOT EXISTS `sync_state` (`id` INTEGER NOT NULL, `ownerDeviceId` TEXT, `verifiedThroughSequence` INTEGER, `verifiedThroughHash` TEXT, `resyncFromStart` INTEGER NOT NULL, PRIMARY KEY(`id`));
CREATE INDEX IF NOT EXISTS `index_resources_assetId` ON `resources` (`assetId`);
CREATE TABLE IF NOT EXISTS room_master_table (id INTEGER PRIMARY KEY,identity_hash TEXT);
